import { Schema } from "effect"

const WebhookDestination = Schema.Struct({
  endpoint: Schema.String,
  signingKeyId: Schema.String
})

export const WebhookEnvelope = Schema.Struct({
  eventId: Schema.String,
  eventType: Schema.Literal("invoice.paid", "invoice.overdue"),
  occurredAt: Schema.String,
  destination: WebhookDestination,
  attributes: Schema.JsonObject
})

export type WebhookEnvelope = typeof WebhookEnvelope.Type

export const decodeWebhookEnvelope = Schema.decodeUnknownSync(WebhookEnvelope)

export function createDeliveryRequest(input: unknown) {
  const envelope = decodeWebhookEnvelope(input)

  return {
    url: envelope.destination.endpoint,
    method: "POST",
    headers: {
      "content-type": "application/json",
      "x-event-id": envelope.eventId,
      "x-signing-key-id": envelope.destination.signingKeyId
    },
    body: JSON.stringify({
      id: envelope.eventId,
      type: envelope.eventType,
      timestamp: envelope.occurredAt,
      attributes: envelope.attributes
    })
  }
}
